140: /** Parses inline emphasis, code spans, and safe links. Raw HTML stays text. */
141: export function parseInline(text: string): MarkdownInline[] {
142:   const nodes: MarkdownInline[] = [];
143:   let buffer = "";
144:   let index = 0;
145: 
146:   const flush = () => {
147:     if (buffer) {
148:       nodes.push({ type: "text", value: buffer });
149:       buffer = "";
150:     }
151:   };
152: 
153:   while (index < text.length) {
154:     const character = text[index];
155:     if (character === "\n") {
156:       flush();
157:       nodes.push({ type: "break" });
158:       index += 1;
159:       continue;
160:     }
161:     if (character === "`") {
162:       const close = findClosing(text, "`", index + 1);
163:       if (close > index + 1) {
164:         flush();
165:         nodes.push({ type: "code", value: text.slice(index + 1, close) });
166:         index = close + 1;
167:         continue;
168:       }
169:     }
170:     if (text.startsWith("**", index) || text.startsWith("__", index)) {
171:       const token = text.slice(index, index + 2);
172:       const close = findClosing(text, token, index + 2);
173:       if (close > index + 2) {
174:         flush();
175:         nodes.push({ type: "strong", children: parseInline(text.slice(index + 2, close)) });
176:         index = close + 2;
177:         continue;
178:       }
179:     }
180:     if (text.startsWith("~~", index)) {
181:       const close = findClosing(text, "~~", index + 2);
182:       if (close > index + 2) {
183:         flush();
184:         nodes.push({ type: "strike", children: parseInline(text.slice(index + 2, close)) });
185:         index = close + 2;
186:         continue;
187:       }
188:     }
189:     if (character === "*" || character === "_") {
190:       const close = findClosing(text, character, index + 1);
191:       if (close > index + 1) {
192:         flush();
193:         nodes.push({ type: "em", children: parseInline(text.slice(index + 1, close)) });
194:         index = close + 1;
195:         continue;
196:       }
197:     }
198:     if (character === "[") {
199:       const labelEnd = text.indexOf("]", index + 1);
200:       const isLink = labelEnd > index + 1 && text[labelEnd + 1] === "(";
201:       const hrefEnd = isLink ? findLinkEnd(text, labelEnd + 2) : -1;
202:       if (isLink && hrefEnd > labelEnd + 2) {
203:         const label = text.slice(index + 1, labelEnd);
204:         const href = safeHref(text.slice(labelEnd + 2, hrefEnd));
205:         flush();
206:         if (href) nodes.push({ type: "link", href, children: parseInline(label) });
207:         else nodes.push({ type: "text", value: label });
208:         index = hrefEnd + 1;
209:         continue;
210:       }
211:     }
212:     buffer += character;
213:     index += 1;
214:   }
215:   flush();
216:   return nodes;
217: }
