219: /** Parses the supported Markdown subset into deterministic blocks. */
220: export function parseMarkdown(source: string): MarkdownBlock[] {
221:   const lines = sanitizeGeneratedMarkdown(source).split("\n");
222:   const blocks: MarkdownBlock[] = [];
223:   let index = 0;
224: 
225:   while (index < lines.length) {
226:     const line = lines[index];
227:     if (isBlank(line)) {
228:       index += 1;
229:       continue;
230:     }
231: 
232:     const fence = fenceMatch(line);
233:     if (fence) {
234:       const marker = fence[1][0];
235:       const language = fence[2] || null;
236:       const code: string[] = [];
237:       index += 1;
238:       while (index < lines.length) {
239:         const candidate = lines[index];
240:         if (new RegExp(`^\\s*${marker}{3,}\\s*$`).test(candidate)) {
241:           index += 1;
242:           break;
243:         }
244:         code.push(candidate);
245:         index += 1;
246:       }
247:       blocks.push({ type: "code", language, code: code.join("\n") });
248:       continue;
249:     }
250: 
251:     const heading = headingMatch(line);
252:     if (heading) {
253:       const text = heading[2].trim();
254:       blocks.push({ type: "heading", level: heading[1].length, text, children: parseInline(text) });
255:       index += 1;
256:       continue;
257:     }
258: 
259:     if (/^\s*([-*_])\s*\1\s*\1[\s\S]*$/.test(line) && !listMatch(line)) {
260:       blocks.push({ type: "hr" });
261:       index += 1;
262:       continue;
263:     }
264: 
265:     if (/^\s*>/.test(line)) {
266:       const quoted: string[] = [];
267:       while (index < lines.length && /^\s*>/.test(lines[index])) {
268:         quoted.push(lines[index].replace(/^\s*>\s?/, ""));
269:         index += 1;
270:       }
271:       const text = quoted.join("\n");
272:       blocks.push({ type: "blockquote", text, children: parseInline(text) });
273:       continue;
274:     }
275: 
276:     const list = listMatch(line);
277:     if (list) {
278:       const items: Array<{ depth: number; text: string; children: MarkdownInline[] }> = [];
279:       let ordered = list.ordered;
280:       while (index < lines.length) {
281:         const current = listMatch(lines[index]);
282:         if (!current) {
283:           if (isBlank(lines[index])) break;
284:           if (items.length && /^\s{2,}\S/.test(lines[index])) {
285:             items[items.length - 1].text += ` ${lines[index].trim()}`;
286:             items[items.length - 1].children = parseInline(items[items.length - 1].text);
287:             index += 1;
288:             continue;
289:           }
290:           break;
291:         }
292:         if (!items.length) ordered = current.ordered;
293:         items.push({ depth: current.depth, text: current.text, children: parseInline(current.text) });
294:         index += 1;
295:       }
296:       blocks.push({ type: "list", ordered, items });
297:       continue;
298:     }
299: 
300:     if (line.includes("|") && index + 1 < lines.length && tableSeparator(lines[index + 1])) {
301:       const header = splitTableRow(line);
302:       const rows: string[][] = [];
303:       index += 2;
304:       while (index < lines.length && lines[index].includes("|") && !isBlank(lines[index])) {
305:         rows.push(splitTableRow(lines[index]));
306:         index += 1;
307:       }
308:       blocks.push({ type: "table", header, rows });
309:       continue;
310:     }
311: 
312:     const paragraph: string[] = [];
313:     while (index < lines.length) {
314:       const candidate = lines[index];
315:       if (isBlank(candidate) || headingMatch(candidate) || fenceMatch(candidate) || listMatch(candidate)
316:         || /^\s*>/.test(candidate) || (candidate.includes("|") && index + 1 < lines.length && tableSeparator(lines[index + 1]))) {
317:         break;
318:       }
319:       paragraph.push(candidate.trim());
320:       index += 1;
321:     }
322:     if (paragraph.length) {
323:       const text = paragraph.join("\n");
324:       blocks.push({ type: "paragraph", text, children: parseInline(text) });
325:     } else {
326:       index += 1;
327:     }
328:   }
329: 
330:   return blocks;
331: }
332: 
333: /** Plain text used for contract coverage checks. */
334: export function markdownPlainText(blocks: MarkdownBlock[]): string {
335:   const parts: string[] = [];
336:   for (const block of blocks) {
337:     if (block.type === "heading" || block.type === "paragraph" || block.type === "blockquote") parts.push(block.text);
338:     else if (block.type === "list") parts.push(...block.items.map((item) => item.text));
339:     else if (block.type === "table") parts.push(...block.header, ...block.rows.flat());
340:     else if (block.type === "code") parts.push(block.code);
341:   }
342:   return parts.join("\n");
343: }

